package contract

import (
	"fmt"
	"strings"

	"github.com/nexssp/kernel/xerr"
)

// RenderNFlow renders valid @schema declarations and a commented pipeline
// example. The commented example keeps the generated file compilable until a
// user adds real actions.
func RenderNFlow(contracts []Contract) (string, error) {
	if len(contracts) == 0 {
		return "", xerr.Validation("no contracts to render")
	}
	if err := ValidateAll(contracts); err != nil {
		return "", err
	}

	var out strings.Builder
	out.WriteString("# Generated by nexss-lang. Review inferred types before use.\n")
	hasRequired := false
	for _, item := range contracts {
		for _, field := range item.Fields {
			if field.Required {
				hasRequired = true
			}
		}
	}
	if hasRequired {
		out.WriteString("# Source-required fields remain marked in inspect JSON; Flow's `validate:\"required\"` also rejects zero values, so it is intentionally omitted here.\n")
	}
	for _, item := range contracts {
		out.WriteByte('\n')
		if item.Description != "" {
			for line := range strings.SplitSeq(item.Description, "\n") {
				out.WriteString("# ")
				out.WriteString(strings.TrimSpace(line))
				out.WriteByte('\n')
			}
		}
		fmt.Fprintf(&out, "@schema %s {\n", item.Name)
		for _, field := range item.Fields {
			typeName, err := nflowType(field.Type, 0)
			if err != nil {
				return "", fmt.Errorf("contract %q field %q: %w", item.Name, field.Name, err)
			}
			fmt.Fprintf(&out, "  %s %s", field.Name, typeName)
			if field.JSONName != "" && field.JSONName != field.Name {
				fmt.Fprintf(&out, " `json:%q`", field.JSONName)
			}
			out.WriteByte('\n')
		}
		out.WriteString("}\n")
	}

	first := contracts[0]
	pipelineName := "handle_" + strings.ToLower(first.Name)
	if !identifier.MatchString(pipelineName) {
		pipelineName = "handle_contract"
	}
	fmt.Fprintf(&out, "\n# Example request boundary (uncomment and add actions):\n# @pipeline %s\n#   :request-schema=%s\n#   # TODO: add actions\n# @end\n", pipelineName, first.Name)
	return out.String(), nil
}

func nflowType(value ValueType, depth int) (string, error) {
	if depth > 16 {
		return "", xerr.Validation("type nesting exceeds 16 levels")
	}
	switch value.Kind {
	case String:
		return "string", nil
	case Integer:
		return "int", nil
	case Number:
		return "float64", nil
	case Boolean:
		return "bool", nil
	case Object:
		return "map[string]any", nil
	case Any:
		return "any", nil
	case Array:
		item := ValueType{Kind: Any}
		if value.Element != nil {
			item = *value.Element
		}
		typeName, err := nflowType(item, depth+1)
		if err != nil {
			return "", err
		}
		return "[]" + typeName, nil
	default:
		return "", fmt.Errorf("unsupported type kind %q", value.Kind)
	}
}
